package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/printer"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"slices"
	"sort"
	"strings"
)

const (
	storeDir        = "tsc/internal/ast/store"
	utilitiesFile   = "utilities.go"
	generatedHeader = "// Code generated by tools/cmd/storetranslate. DO NOT EDIT."
)

// run is the translation (7d-2a instructions 3):
//
//  1. load the Pointer packages and package store, with the generated files
//     of the output packages read as empty;
//  2. the reach (reach.go) decides what each output package gets;
//  3. phase 1: the stubs, every output declaration with its Store signature
//     and an empty body, are printed with placeholder types;
//  4. phase 2: the packages are loaded again with the output packages made of
//     the stubs, the P2 files and the hand-written files, so that the
//     translation of a body sees the Store types of every output declaration;
//  5. every output declaration is translated and written.
//
// A construct no rule covers is a problem; the translation stops and prints
// them without writing anything.
func run(root, binderOut, verbatim string) error {
	w2, res, err := prepare(root)
	if err != nil {
		return err
	}
	out, problems := emitAll(w2, res, false)
	stubErrors := stubTypeErrors(w2)
	if dir := os.Getenv("STORETRANSLATE_DUMP"); dir != "" {
		_ = os.MkdirAll(dir, 0o755)
		sort.Strings(w2.u.r4Sites)
		_ = os.WriteFile(filepath.Join(dir, "r4sites.txt"), []byte(strings.Join(w2.u.r4Sites, "\n")+"\n"), 0o644)
		sort.Strings(w2.u.r8Sites)
		_ = os.WriteFile(filepath.Join(dir, "r8sites.txt"), []byte(strings.Join(w2.u.r8Sites, "\n")+"\n"), 0o644)
	}
	if len(problems) > 0 || os.Getenv("STORETRANSLATE_FORCE") != "" {
		if dir := os.Getenv("STORETRANSLATE_DUMP"); dir != "" {
			if err := dump(dir, root, out, problems, stubErrors); err != nil {
				return err
			}
		}
	}
	if len(problems) > 0 && os.Getenv("STORETRANSLATE_FORCE") == "" {
		return fmt.Errorf("the rules do not translate these declarations; write them in a *_manual.go file (P2):\n%s%d problems", strings.Join(problems, ""), len(problems))
	}
	if err := writeOutputs(w2, out); err != nil {
		return err
	}
	fmt.Print(reachReport(w2, res))
	sort.Strings(w2.u.r4Sites)
	fmt.Printf("R4': %d copies with Nodes()\n", len(w2.u.r4Sites))
	for _, site := range w2.u.r4Sites {
		fmt.Printf("  %s\n", site)
	}
	if binderOut != "" {
		return binderTrial(w2, binderOut, verbatim)
	}
	return nil
}

// prepare is steps 1 to 4 of run: the phase 2 world and the reach.
func prepare(root string) (*world, *reachResult, error) {
	w1, err := loadWorld(root, nil)
	if err != nil {
		return nil, nil, err
	}
	if err := readManuals(w1); err != nil {
		return nil, nil, err
	}
	res, err := computeReach(w1)
	if err != nil {
		return nil, nil, err
	}
	w1.u.res = res
	stubs, _ := emitAll(w1, res, true)
	for _, o := range w1.outs {
		if err := mustMkdir(o.dir); err != nil {
			return nil, nil, err
		}
	}
	w2, err := loadWorld(root, stubs)
	if err != nil {
		return nil, nil, err
	}
	if err := readManuals(w2); err != nil {
		return nil, nil, err
	}
	w2.u.res = res
	w2.u.changedType = changedTypeFor(w2, res)
	return w2, res, nil
}

// listDraft prints the draft of the List version of Pointer functions (3.4):
// the function translated with its []*ast.Node parameters as store.List, so
// that the List rules apply to their uses, and named <F>List, after its
// pointer-hash line. It is a draft for a P2 file, not an output.
func listDraft(root, names string) error {
	w, _, err := prepare(root)
	if err != nil {
		return err
	}
	for _, name := range strings.Split(names, ",") {
		pkg, key := "ast", name
		if i := strings.Index(name, "."); i >= 0 && w.outs[internal+name[:i]] != nil {
			pkg, key = name[:i], name[i+1:]
		}
		d := w.decl(internal+pkg, key)
		if d == nil {
			return fmt.Errorf("no declaration %s", name)
		}
		fd, ok := d.node.(*ast.FuncDecl)
		if !ok {
			return fmt.Errorf("%s is not a function", name)
		}
		o := d.out
		imports := map[string]string{}
		tr := &translator{universe: w.u, fset: w.fset, src: o.pkg.Types, info: o.pkg.TypesInfo, out: &target{o: o, name: o.name, path: o.path, imports: imports}}
		f := tr.newFn(fd)
		f.listParams = true
		out := f.funcDecl(fd)
		out.Name = ident(fd.Name.Name+"List", fd.Name.Pos())
		text, err := render(w.fset, o.name, imports, []ast.Decl{out}, commentsIn(w, d.file, fd), "")
		if err != nil {
			return err
		}
		fmt.Printf("// storetranslate:pointer-hash %s %s:%s\n", d.hash(), d.fileName, key)
		body := string(text)
		if i := strings.Index(body, "func "); i >= 0 {
			body = body[i:]
		}
		fmt.Print(body)
		for _, p := range f.problems {
			fmt.Printf("// PROBLEM %s: %s\n", relPos(root, p.pos.String()), p.msg)
		}
		fmt.Println()
	}
	return nil
}

// changedTypeFor is the reach's changedType on the world w.
func changedTypeFor(w *world, res *reachResult) func(*types.Named) bool {
	return func(n *types.Named) bool {
		o := w.outs[pkgPathOf(n.Obj())]
		if o == nil {
			return false
		}
		switch o.mode {
		case modeFull:
			return true
		case modeAST:
			return w.u.astTypeInStore(n)
		case modeFile:
			d := w.decl(o.srcPath, n.Obj().Name())
			return d != nil && o.isFileLevel(d.fileName)
		}
		return res.output[o.srcPath+"."+n.Obj().Name()]
	}
}

// stubTypeErrors are the type errors of the output packages made of stubs:
// a declaration whose Store signature or type does not type-check.
func stubTypeErrors(w *world) []string {
	var out []string
	for _, o := range w.outs {
		pkg := w.byPath[o.path]
		if pkg == nil {
			continue
		}
		for _, e := range pkg.Errors {
			out = append(out, e.Error())
		}
	}
	sort.Strings(out)
	return out
}

// dump writes the outputs and the problems into dir, for looking at a
// translation that does not finish.
func dump(dir, root string, out map[string][]byte, problems, stubErrors []string) error {
	for path, text := range out {
		rel, _ := filepath.Rel(filepath.Join(root, "tsc/internal"), path)
		target := filepath.Join(dir, rel+".txt")
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(target, text, 0o644); err != nil {
			return err
		}
	}
	if err := os.WriteFile(filepath.Join(dir, "problems.txt"), []byte(strings.Join(problems, "")), 0o644); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, "stub-errors.txt"), []byte(strings.Join(stubErrors, "\n")+"\n"), 0o644)
}

// writeOutputs writes every output file and removes the generated files that
// were not written again.
func writeOutputs(w *world, out map[string][]byte) error {
	for path, text := range out {
		if err := os.WriteFile(path, text, 0o644); err != nil {
			return err
		}
	}
	for _, o := range w.outs {
		for name := range o.generated {
			path := filepath.Join(o.dir, name)
			if _, ok := out[path]; !ok {
				if err := os.Remove(path); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

// ── Emitting ──

// emitFile is one output file under construction.
type emitFile struct {
	o        *outPkg
	path     string
	header   string
	decls    []ast.Decl
	comments []*ast.CommentGroup
	imports  map[string]string
	src      []string // the source files
}

// emitAll translates the reached declarations of every output package: with
// stub, the stubs of phase 1; otherwise the output. It returns the files by
// absolute path, and the problems.
func emitAll(w *world, res *reachResult, stub bool) (map[string][]byte, []string) {
	files := map[string]*emitFile{}
	var problems []string
	var order []string
	get := func(o *outPkg, fileName string) *emitFile {
		name := fileName
		if o.mode == modeAST && !o.isFileLevel(fileName) {
			name = utilitiesFile
		}
		path := o.outputFile(name)
		ef, ok := files[path]
		if !ok {
			ef = &emitFile{o: o, path: path, imports: map[string]string{}}
			files[path] = ef
			order = append(order, path)
		}
		if !slices.Contains(ef.src, fileName) {
			ef.src = append(ef.src, fileName)
		}
		return ef
	}
	for _, o := range sortedOuts(w) {
		keys, keyProblems := keyFields(w.u, w.fset, o.pkg.Types, o.pkg.TypesInfo, o.pkg.Syntax)
		w.u.keyFields = keys
		if !stub {
			for _, p := range keyProblems {
				problems = append(problems, fmt.Sprintf("  %s: %s\n", relPos(w.root, p.pos.String()), p.msg))
			}
		}
		var srcFiles []*ast.File
		for _, file := range o.pkg.Syntax {
			if !strings.HasSuffix(w.fset.Position(file.Pos()).Filename, "_test.go") {
				srcFiles = append(srcFiles, file)
			}
		}
		// The order of 7d-0: file name, then offset.
		sort.Slice(srcFiles, func(i, j int) bool {
			return w.fset.Position(srcFiles[i].Pos()).Filename < w.fset.Position(srcFiles[j].Pos()).Filename
		})
		for _, file := range srcFiles {
			fileName := filepath.Base(w.fset.Position(file.Pos()).Filename)
			for _, d := range file.Decls {
				part := outputPart(w, res, o, fileName, d)
				if part == nil {
					continue
				}
				ef := get(o, fileName)
				tr := &translator{universe: w.u, fset: w.fset, src: o.pkg.Types, info: o.pkg.TypesInfo, out: &target{o: o, name: o.name, path: o.path, imports: ef.imports}}
				decl, ps := emitDecl(tr, part, stub)
				ef.decls = append(ef.decls, decl)
				if !stub {
					ef.comments = append(ef.comments, commentsIn(w, file, part)...)
					for _, p := range ps {
						problems = append(problems, fmt.Sprintf("  %s: %s: %s\n", relPos(w.root, p.pos.String()), declLabel(part), p.msg))
					}
				}
			}
		}
		w.u.keyFields = nil
	}
	out := map[string][]byte{}
	for _, path := range order {
		ef := files[path]
		header := fmt.Sprintf("%s\n\n// Translated from %s by tools/cmd/storetranslate.\n", generatedHeader, strings.Join(ef.src, ", "))
		if ef.o.mode == modeAST && filepath.Base(path) == utilitiesFile {
			header = utilitiesHeader(res, len(ef.decls))
		}
		text, err := render(w.fset, ef.o.name, ef.imports, ef.decls, ef.comments, header)
		if err != nil {
			problems = append(problems, fmt.Sprintf("  %s: %v\n", relPos(w.root, path), err))
		}
		out[path] = text
	}
	return out, problems
}

func sortedOuts(w *world) []*outPkg {
	var out []*outPkg
	for _, o := range w.outs {
		out = append(out, o)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].src < out[j].src })
	return out
}

// outputPart is the part of a top-level declaration that the reach outputs:
// the declaration, a GenDecl with the output specs only (a const group whole,
// for iota), or nil.
func outputPart(w *world, res *reachResult, o *outPkg, fileName string, d ast.Decl) ast.Decl {
	switch d := d.(type) {
	case *ast.FuncDecl:
		key := declNames(d)[0]
		if d.Name.Name == "init" {
			key = fmt.Sprintf("init#%d", w.fset.Position(d.Pos()).Offset) + "@" + fileName
		}
		if res.output[o.srcPath+"."+key] {
			return d
		}
	case *ast.GenDecl:
		if d.Tok == token.IMPORT {
			return nil
		}
		var specs []ast.Spec
		for _, s := range d.Specs {
			for _, name := range declNames(&ast.GenDecl{Tok: d.Tok, Specs: []ast.Spec{s}}) {
				if res.output[o.srcPath+"."+name] {
					specs = append(specs, s)
					break
				}
			}
		}
		if len(specs) == 0 {
			return nil
		}
		if d.Tok == token.CONST || len(specs) == len(d.Specs) {
			return d
		}
		out := *d
		out.Specs = specs
		if len(specs) == 1 {
			out.Lparen, out.Rparen = token.NoPos, token.NoPos
		}
		return &out
	}
	return nil
}

func declLabel(d ast.Decl) string {
	names := declNames(d)
	if len(names) == 0 {
		return "?"
	}
	return names[0]
}

// emitDecl translates a declaration, or with stub makes its stub: the Store
// signature of a function with a body that panics, a variable without its
// value.
func emitDecl(tr *translator, d ast.Decl, stub bool) (ast.Decl, []problem) {
	switch d := d.(type) {
	case *ast.FuncDecl:
		f := tr.newFn(d)
		if stub {
			sig, _ := f.info.Defs[d.Name].Type().(*types.Signature)
			f.pushResults(sig)
			out := &ast.FuncDecl{Recv: f.fields(d.Recv), Name: d.Name, Type: f.funcType(d.Type), Body: stubBody(d.Body.Lbrace)}
			return out, f.problems
		}
		out := f.funcDecl(d)
		tr.r4Sites = append(tr.r4Sites, f.r4Sites...)
		tr.r8Sites = append(tr.r8Sites, f.r8Sites...)
		return out, f.problems
	case *ast.GenDecl:
		f := tr.newFn(d)
		if stub && d.Tok == token.VAR {
			out := &ast.GenDecl{TokPos: d.TokPos, Tok: d.Tok, Lparen: d.Lparen, Rparen: d.Rparen}
			for _, s := range d.Specs {
				vs := s.(*ast.ValueSpec)
				spec := &ast.ValueSpec{Names: vs.Names}
				if vs.Type != nil {
					spec.Type = f.typ(vs.Type)
				} else if obj := f.info.Defs[vs.Names[0]]; obj != nil {
					m, _ := f.mapType(obj.Type())
					spec.Type = f.typeExpr(m, vs.Pos())
				}
				out.Specs = append(out.Specs, spec)
			}
			return out, f.problems
		}
		out := f.genDecl(d)
		tr.r4Sites = append(tr.r4Sites, f.r4Sites...)
		return out, f.problems
	}
	return nil, nil
}

func stubBody(pos token.Pos) *ast.BlockStmt {
	return &ast.BlockStmt{Lbrace: pos, Rbrace: pos, List: []ast.Stmt{
		&ast.ExprStmt{X: call(ident("panic", pos), pos, &ast.BasicLit{ValuePos: pos, Kind: token.STRING, Value: `"storetranslate: stub"`})},
	}}
}

// utilitiesHeader is the comment at the top of store/utilities.go.
func utilitiesHeader(res *reachResult, n int) string {
	return generatedHeader + "\n\n" +
		"// The predicates and helpers of package ast that the Store code reads a node\n" +
		"// with, translated by the rules of tools/cmd/storetranslate (U2,\n" +
		"// internal/ast/docs/store-checker-design-20260923.md 2.1). The functions the\n" +
		"// rules do not cover are written by hand in utilities_manual.go (P2).\n" +
		"//\n" +
		fmt.Sprintf("// Reach: %d functions of package ast that the roots of tools/cmd/storetranslate\n// name in their bodies, called or as a value, transitively.\n", n)
}

// reachReport is the table of 3.2: the reached functions and methods of each
// output file, and the functions and methods of its source.
func reachReport(w *world, res *reachResult) string {
	type row struct{ reached, total, p2 int }
	rows := map[string]*row{}
	for key, d := range w.decls {
		if _, ok := d.node.(*ast.FuncDecl); !ok || strings.HasPrefix(d.key, "init#") {
			continue
		}
		name := d.out.src + "/" + d.fileName
		r := rows[name]
		if r == nil {
			r = &row{}
			rows[name] = r
		}
		r.total++
		if res.output[key] {
			r.reached++
		}
		if _, ok := d.out.manual[d.key]; ok {
			r.p2++
		}
	}
	var names []string
	for n := range rows {
		if rows[n].reached+rows[n].p2 > 0 {
			names = append(names, n)
		}
	}
	sort.Strings(names)
	var b strings.Builder
	b.WriteString("reach: functions and methods translated / P2 / in the source file\n")
	for _, n := range names {
		r := rows[n]
		fmt.Fprintf(&b, "  %-44s %5d %4d %5d\n", n, r.reached, r.p2, r.total)
	}
	return b.String()
}

// ── Output ──

// commentsIn are the comment groups of a declaration, its doc included.
func commentsIn(w *world, file *ast.File, d ast.Decl) []*ast.CommentGroup {
	from := d.Pos()
	switch x := d.(type) {
	case *ast.FuncDecl:
		if x.Doc != nil {
			from = x.Doc.Pos()
		}
	case *ast.GenDecl:
		if x.Doc != nil {
			from = x.Doc.Pos()
		}
	}
	var out []*ast.CommentGroup
	for _, c := range file.Comments {
		if c.Pos() >= from && c.End() <= d.End() {
			out = append(out, c)
		}
	}
	return out
}

// render prints the declarations in order with their comments, then formats
// the file.
func render(fset *token.FileSet, pkg string, imports map[string]string, decls []ast.Decl, comments []*ast.CommentGroup, header string) ([]byte, error) {
	var body bytes.Buffer
	cfg := &printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
	for _, d := range decls {
		var own []*ast.CommentGroup
		from, to := d.Pos(), d.End()
		switch x := d.(type) {
		case *ast.FuncDecl:
			if x.Doc != nil {
				from = x.Doc.Pos()
				x.Doc = nil // printed from the comment list instead
			}
		case *ast.GenDecl:
			if x.Doc != nil {
				from = x.Doc.Pos()
				x.Doc = nil
			}
		}
		for _, c := range comments {
			if c.Pos() >= from && c.End() <= to {
				own = append(own, c)
			}
		}
		if err := cfg.Fprint(&body, fset, &printer.CommentedNode{Node: d, Comments: own}); err != nil {
			return nil, err
		}
		body.WriteString("\n\n")
	}
	var out bytes.Buffer
	out.WriteString(header)
	fmt.Fprintf(&out, "\npackage %s\n\n", pkg)
	// The standard library first, then the rest, as goimports groups them.
	var std, other []string
	for path := range imports {
		if strings.Contains(strings.Split(path, "/")[0], ".") {
			other = append(other, path)
		} else {
			std = append(std, path)
		}
	}
	slices.Sort(std)
	slices.Sort(other)
	if len(std)+len(other) > 0 {
		out.WriteString("import (\n")
		for _, path := range std {
			if name := imports[path]; name != filepath.Base(path) {
				fmt.Fprintf(&out, "\t%s %q\n", name, path)
			} else {
				fmt.Fprintf(&out, "\t%q\n", path)
			}
		}
		if len(std) > 0 && len(other) > 0 {
			out.WriteString("\n")
		}
		for _, path := range other {
			if name := imports[path]; name != filepath.Base(path) {
				fmt.Fprintf(&out, "\t%s %q\n", name, path)
			} else {
				fmt.Fprintf(&out, "\t%q\n", path)
			}
		}
		out.WriteString(")\n\n")
	}
	out.Write(body.Bytes())
	formatted, err := format.Source(out.Bytes())
	if err != nil {
		return out.Bytes(), fmt.Errorf("format: %w", err)
	}
	return formatted, nil
}

func relPos(root, pos string) string {
	return strings.TrimPrefix(pos, root+"/")
}
